def replace(yaml_dict, template_dict):
    """Replace matched {{...}} in template_dict with values from yaml_dict

    :param yaml_dict: dict representation of a YAML document defining
    placeholder values
    :type yaml_dict: dict
    :param template_dict: dict representation of a YAML document containing
    '{{...}}' string placeholders
    :type template_dict: dict
    :raises PlaceholderNotFoundError: a {{...}} placeholder in template_dict
    was not found
    :raises ValueError: at least one input parameter is invalid
    :raises NotImplementedError: [description]
    :return: yaml_dict with all '{{...}}' replaced
    :rtype: dict
    """

    # pre-compile the {{...}} placeholder search expression
    # outside `do_replace` to avoid doing it multiple times
    p = re.compile(r'{{([\w\.]+)}}', re.VERBOSE)

    def get_comment_for_key(parent_dict, key):
        """Extract comment for a key from a CommentedDict if available."""
        if hasattr(parent_dict, 'ca') and hasattr(parent_dict.ca, 'items'):
            comment_info = parent_dict.ca.items.get(key)
            if comment_info and len(comment_info) > 2 and comment_info[2]:
                return comment_info[2].value.strip()
        return None

    def is_optional_comment(comment):
        """Check if comment contains @optional annotation."""
        return comment and '@optional' in comment

    def is_annotation_only_comment(comment):
        """Check if comment contains @annotation_only annotation."""
        return comment and '@annotation_only' in comment

    def process_string(yaml_dict, str, is_optional=False, is_annotation_only=False, placeholder_name=None):
        # determine whether {{...}} placeholder
        # replacement is required
        r = p.search(str)
        if r is None:
            return str
        else:
            # If annotation_only, return the placeholder as-is
            if is_annotation_only:
                return str

            # Try to find the value
            root = yaml_dict
            for property in r.group(1).split('.'):
                root = root.get(property)
                if root is None:
                    # If optional, return None instead of raising error
                    if is_optional:
                        return None
                    else:
                        raise PlaceholderNotFoundError(r.group(1))
            return root

    def process_list(yaml_dict, list_in, is_optional=False, is_annotation_only=False):
        list_out = []
        for v in list_in:
            # if v is a string process it
            if(isinstance(v, str)):
                list_out.append(process_string(yaml_dict, v, is_optional, is_annotation_only))
            elif(isinstance(v, dict)):
                list_out.append(do_replace(yaml_dict, v))
            elif(isinstance(v, list)):
                list_out.append(process_list(yaml_dict, v, is_optional, is_annotation_only))
            else:
                raise NotImplementedError(
                        'Support for properties of type {} in lists '
                        'is not implemented.'
                        .format(type(v)))
        return list_out

    # Recursive function does the actual work
    def do_replace(yaml_dict, template_dict):

        if yaml_dict is None or template_dict is None:
            # nothing to do
            return None

        if not isinstance(yaml_dict, dict):
            raise ValueError('Parameter \'yaml_dict\' must be of type '
                             '\'dict\' not {}.'.format(type(yaml_dict)))

        if not isinstance(template_dict, dict):
            raise ValueError('Parameter \'template_dict\' must be of type '
                             '\'dict\' not {}.'.format(type(template_dict)))

        template_out = {}
        # replace placeholders in the template, one value at a time
        for key in template_dict.keys():
            val = template_dict[key]

            # Get comment for this key to check for annotations
            comment = get_comment_for_key(template_dict, key)
            is_optional = is_optional_comment(comment)
            is_annotation_only = is_annotation_only_comment(comment)

            # print('Key: {} Value: {} Type: {}'.format(key, val, type(val)))
            if val is None:
                # NoneType - no value
                template_out[key] = None
            elif isinstance(val, str):
                # process string
                # Extract placeholder name for potential error reporting
                placeholder_match = p.search(val)
                placeholder_name = placeholder_match.group(1) if placeholder_match else None
                template_out[key] = process_string(yaml_dict, val, is_optional, is_annotation_only, placeholder_name)
            elif isinstance(val, dict):
                # process the dictionary recursively
                template_out[key] = do_replace(yaml_dict, val)
            elif isinstance(val, list):
                # process each list item
                template_out[key] = process_list(yaml_dict, val, is_optional, is_annotation_only)
            else:
                raise NotImplementedError(
                        'Support for properties of type {} is not implemented.'
                        .format(type(val)))

        return template_out

    return do_replace(yaml_dict, template_dict)

